// The data URL already contains every byte, so `/1.1` admits it as an inline
// non-capability. Its code still receives Quarantine identity and must never
// borrow this package's positive authority.
export async function pull() {
  const name = "ODEN_DATA_IMPORT_SECRET";
  const packageValue = Deno.env.get(name);
  const source = `
    export function probe(name) {
      try {
        return "BORROWED:" + Deno.env.get(name);
      } catch (error) {
        return error?.name === "NotCapable" &&
            String(error?.message).includes('principal "quarantine"')
          ? "QUARANTINE_DENIED"
          : "BROKEN:" + error?.name + ":" + error?.message;
      }
    }
  `;
  const module = await import(
    `data:text/javascript,${encodeURIComponent(source)}`
  );
  return `package ${packageValue} data ${module.probe(name)}`;
}
